extern void Log(const char* fmt, ...);

#define LOG_2D(fmt, ...) Log("[VULKAN_2D] " fmt, ##__VA_ARGS__)

Vulkan2D& Vulkan2D::Get() {
    static Vulkan2D s_instance;
    return s_instance;
}

Vulkan2D::Vulkan2D() = default;

Vulkan2D::~Vulkan2D() {
    Shutdown();
}

uint32_t Vulkan2D::FindMemoryType(uint32_t typeFilter, VkMemoryPropertyFlags properties) {
    if (m_physicalDevice == VK_NULL_HANDLE) return UINT32_MAX;
    VkPhysicalDeviceMemoryProperties memProperties = {};
    vkGetPhysicalDeviceMemoryProperties(m_physicalDevice, &memProperties);

    for (uint32_t i = 0; i < memProperties.memoryTypeCount; i++) {
        if ((typeFilter & (1u << i)) && (memProperties.memoryTypes[i].propertyFlags & properties) == properties) {
            return i;
        }
    }
    return UINT32_MAX;
}

bool Vulkan2D::Initialize(VkDevice device,
                          VkPhysicalDevice physicalDevice,
                          VkQueue graphicsQueue,
                          uint32_t graphicsQueueFamily,
                          VkFormat colorFormat,
                          uint32_t width,
                          uint32_t height) {
    if (m_bInitialized) {
        LOG_2D("Already initialized. Resizing viewport to %ux%u", width, height);
        Resize(width, height);
        return true;
    }

    if (!device || !physicalDevice || !graphicsQueue) {
        LOG_2D("Skipping Vulkan2D initialization: VkDevice (0x%p), VkPhysicalDevice (0x%p), or VkQueue (0x%p) is VK_NULL_HANDLE.",
               device, physicalDevice, graphicsQueue);
        return false;
    }

    LOG_2D("================================================================================");
    LOG_2D("INITIALIZING NATIVE VULKAN 2D IMMEDIATE PIPELINE & MEMORY SCAFFOLDING");
    LOG_2D("Device: 0x%p, PhysicalDevice: 0x%p, Format: %d, Initial Extent: %ux%u",
           device, physicalDevice, colorFormat, width, height);
    LOG_2D("================================================================================");

    m_device = device;
    m_physicalDevice = physicalDevice;
    m_graphicsQueue = graphicsQueue;
    m_graphicsQueueFamily = graphicsQueueFamily;
    m_colorFormat = colorFormat;
    m_width = width;
    m_height = height;
    m_activeFrameSlot = 0;
    m_hasStartedAnyFrame = false;

    if (!CreateBuffers()) {
        LOG_2D("FATAL: Failed to allocate dynamic 2D ring buffers!");
        Shutdown();
        return false;
    }

    if (!CreateRenderPass(colorFormat)) {
        LOG_2D("FATAL: Failed to create 2D render pass!");
        Shutdown();
        return false;
    }

    if (!CreateWhiteFallbackTexture()) {
        LOG_2D("FATAL: Failed to create white fallback texture descriptor!");
        Shutdown();
        return false;
    }

    if (!CreatePipeline()) {
        LOG_2D("FATAL: Failed to create 2D graphics pipeline!");
        Shutdown();
        return false;
    }

    m_bInitialized = true;
    LOG_2D("Native Vulkan 2D immediate subsystem successfully initialized! (Buffers: %u x 4 MB Coherent Ring)",
           MAX_FRAMES_IN_FLIGHT);
    return true;
}

void Vulkan2D::Resize(uint32_t width, uint32_t height) {
    m_width = width;
    m_height = height;
    LOG_2D("Viewport resized to %ux%u", width, height);
}

bool Vulkan2D::CreateBuffers() {
    LOG_2D("Allocating %u per-frame dynamic host-visible coherent vertex/index ring slots...", MAX_FRAMES_IN_FLIGHT);

    const VkMemoryPropertyFlags hostCoherentFlags =
        VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT;

    for (uint32_t slot = 0; slot < MAX_FRAMES_IN_FLIGHT; ++slot) {
        FrameRingSlot& ring = m_frameRings[slot];

        // 1. Per-Frame Vertex Buffer (2 MB)
        VkBufferCreateInfo vtxInfo = {};
        vtxInfo.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
        vtxInfo.size = VTX_BUFFER_SIZE;
        vtxInfo.usage = VK_BUFFER_USAGE_VERTEX_BUFFER_BIT;
        vtxInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;

        if (vkCreateBuffer(m_device, &vtxInfo, nullptr, &ring.vtxBuffer) != VK_SUCCESS) {
            LOG_2D("ERROR: vkCreateBuffer failed for vertex buffer (slot %u)!", slot);
            return false;
        }

        VkMemoryRequirements vtxMemReq = {};
        vkGetBufferMemoryRequirements(m_device, ring.vtxBuffer, &vtxMemReq);

        uint32_t vtxMemType = FindMemoryType(vtxMemReq.memoryTypeBits, hostCoherentFlags);
        if (vtxMemType == UINT32_MAX) {
            LOG_2D("ERROR: Suitable HOST_VISIBLE|HOST_COHERENT memory type not found for vertex buffer (slot %u)!", slot);
            return false;
        }

        VkMemoryAllocateInfo vtxAlloc = {};
        vtxAlloc.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
        vtxAlloc.allocationSize = vtxMemReq.size;
        vtxAlloc.memoryTypeIndex = vtxMemType;

        if (vkAllocateMemory(m_device, &vtxAlloc, nullptr, &ring.vtxMemory) != VK_SUCCESS) {
            LOG_2D("ERROR: vkAllocateMemory failed for vertex buffer memory (slot %u)!", slot);
            return false;
        }

        vkBindBufferMemory(m_device, ring.vtxBuffer, ring.vtxMemory, 0);

        if (vkMapMemory(m_device, ring.vtxMemory, 0, VTX_BUFFER_SIZE, 0, reinterpret_cast<void**>(&ring.pMappedVertices)) != VK_SUCCESS ||
            !ring.pMappedVertices) {
            LOG_2D("ERROR: vkMapMemory failed for vertex buffer (slot %u)!", slot);
            return false;
        }

        // 2. Per-Frame Index Buffer (2 MB)
        VkBufferCreateInfo idxInfo = {};
        idxInfo.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
        idxInfo.size = IDX_BUFFER_SIZE;
        idxInfo.usage = VK_BUFFER_USAGE_INDEX_BUFFER_BIT;
        idxInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;

        if (vkCreateBuffer(m_device, &idxInfo, nullptr, &ring.idxBuffer) != VK_SUCCESS) {
            LOG_2D("ERROR: vkCreateBuffer failed for index buffer (slot %u)!", slot);
            return false;
        }

        VkMemoryRequirements idxMemReq = {};
        vkGetBufferMemoryRequirements(m_device, ring.idxBuffer, &idxMemReq);

        uint32_t idxMemType = FindMemoryType(idxMemReq.memoryTypeBits, hostCoherentFlags);
        if (idxMemType == UINT32_MAX) {
            LOG_2D("ERROR: Suitable HOST_VISIBLE|HOST_COHERENT memory type not found for index buffer (slot %u)!", slot);
            return false;
        }

        VkMemoryAllocateInfo idxAlloc = {};
        idxAlloc.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
        idxAlloc.allocationSize = idxMemReq.size;
        idxAlloc.memoryTypeIndex = idxMemType;

        if (vkAllocateMemory(m_device, &idxAlloc, nullptr, &ring.idxMemory) != VK_SUCCESS) {
            LOG_2D("ERROR: vkAllocateMemory failed for index buffer memory (slot %u)!", slot);
            return false;
        }

        vkBindBufferMemory(m_device, ring.idxBuffer, ring.idxMemory, 0);

        if (vkMapMemory(m_device, ring.idxMemory, 0, IDX_BUFFER_SIZE, 0, reinterpret_cast<void**>(&ring.pMappedIndices)) != VK_SUCCESS ||
            !ring.pMappedIndices) {
            LOG_2D("ERROR: vkMapMemory failed for index buffer (slot %u)!", slot);
            return false;
        }

        LOG_2D("Ring Slot %u: VTX=%lluB (0x%p), IDX=%lluB (0x%p)",
               slot,
               static_cast<unsigned long long>(VTX_BUFFER_SIZE), ring.pMappedVertices,
               static_cast<unsigned long long>(IDX_BUFFER_SIZE), ring.pMappedIndices);
    }

    return true;
}

bool Vulkan2D::CreateRenderPass(VkFormat colorFormat) {
    VkAttachmentDescription colorAttachment = {};
    colorAttachment.format = colorFormat;
    colorAttachment.samples = VK_SAMPLE_COUNT_1_BIT;
    colorAttachment.loadOp = VK_ATTACHMENT_LOAD_OP_LOAD; // Preserve underlying 3D scene
    colorAttachment.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
    colorAttachment.stencilLoadOp = VK_ATTACHMENT_LOAD_OP_DONT_CARE;
    colorAttachment.stencilStoreOp = VK_ATTACHMENT_STORE_OP_DONT_CARE;
    colorAttachment.initialLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
    colorAttachment.finalLayout = VK_IMAGE_LAYOUT_PRESENT_SRC_KHR;

    VkAttachmentReference colorAttachmentRef = {};
    colorAttachmentRef.attachment = 0;
    colorAttachmentRef.layout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;

    VkSubpassDescription subpass = {};
    subpass.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
    subpass.colorAttachmentCount = 1;
    subpass.pColorAttachments = &colorAttachmentRef;

    VkSubpassDependency dependency = {};
    dependency.srcSubpass = VK_SUBPASS_EXTERNAL;
    dependency.dstSubpass = 0;
    dependency.srcStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    dependency.srcAccessMask = 0;
    dependency.dstStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
    dependency.dstAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;

    VkRenderPassCreateInfo renderPassInfo = {};
    renderPassInfo.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO;
    renderPassInfo.attachmentCount = 1;
    renderPassInfo.pAttachments = &colorAttachment;
    renderPassInfo.subpassCount = 1;
    renderPassInfo.pSubpasses = &subpass;
    renderPassInfo.dependencyCount = 1;
    renderPassInfo.pDependencies = &dependency;

    if (vkCreateRenderPass(m_device, &renderPassInfo, nullptr, &m_renderPass) != VK_SUCCESS) {
        LOG_2D("ERROR: vkCreateRenderPass failed!");
        return false;
    }

    LOG_2D("Created VkRenderPass (Handle: 0x%p, Format: %d)", m_renderPass, colorFormat);
    return true;
}

bool Vulkan2D::CreateWhiteFallbackTexture() {
    LOG_2D("Creating 4x4 white fallback texture (OPTIMAL tiling + SHADER_READ_ONLY_OPTIMAL barrier)...");

    constexpr VkDeviceSize kWhitePixelBytes = 4 * 4 * 4; // 64 bytes RGBA8

    // 1. Staging Buffer (64B pure white 0xFFFFFFFF)
    VkBuffer stagingBuffer = VK_NULL_HANDLE;
    VkDeviceMemory stagingMemory = VK_NULL_HANDLE;

    VkBufferCreateInfo stgInfo = {};
    stgInfo.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
    stgInfo.size = kWhitePixelBytes;
    stgInfo.usage = VK_BUFFER_USAGE_TRANSFER_SRC_BIT;
    stgInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    if (vkCreateBuffer(m_device, &stgInfo, nullptr, &stagingBuffer) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create staging buffer for white fallback texture!");
        return false;
    }

    VkMemoryRequirements stgReqs = {};
    vkGetBufferMemoryRequirements(m_device, stagingBuffer, &stgReqs);
    uint32_t stgMemType = FindMemoryType(stgReqs.memoryTypeBits,
                                         VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
    if (stgMemType == UINT32_MAX) {
        LOG_2D("ERROR: Suitable memory type not found for white texture staging buffer!");
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        return false;
    }

    VkMemoryAllocateInfo stgAlloc = {};
    stgAlloc.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    stgAlloc.allocationSize = stgReqs.size;
    stgAlloc.memoryTypeIndex = stgMemType;
    if (vkAllocateMemory(m_device, &stgAlloc, nullptr, &stagingMemory) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to allocate white texture staging memory!");
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        return false;
    }
    vkBindBufferMemory(m_device, stagingBuffer, stagingMemory, 0);

    void* pStagingData = nullptr;
    if (vkMapMemory(m_device, stagingMemory, 0, kWhitePixelBytes, 0, &pStagingData) != VK_SUCCESS || !pStagingData) {
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        vkFreeMemory(m_device, stagingMemory, nullptr);
        return false;
    }
    std::memset(pStagingData, 0xFF, static_cast<size_t>(kWhitePixelBytes));
    vkUnmapMemory(m_device, stagingMemory);

    // 2. Optimal-tiled Device Image starting in UNDEFINED and transitioned to SHADER_READ_ONLY_OPTIMAL
    VkImageCreateInfo imgInfo = {};
    imgInfo.sType = VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO;
    imgInfo.imageType = VK_IMAGE_TYPE_2D;
    imgInfo.extent.width = 4;
    imgInfo.extent.height = 4;
    imgInfo.extent.depth = 1;
    imgInfo.mipLevels = 1;
    imgInfo.arrayLayers = 1;
    imgInfo.format = VK_FORMAT_R8G8B8A8_UNORM;
    imgInfo.tiling = VK_IMAGE_TILING_OPTIMAL;
    imgInfo.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
    imgInfo.usage = VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_SAMPLED_BIT;
    imgInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    imgInfo.samples = VK_SAMPLE_COUNT_1_BIT;

    if (vkCreateImage(m_device, &imgInfo, nullptr, &m_whiteImage) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create white fallback VkImage!");
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        vkFreeMemory(m_device, stagingMemory, nullptr);
        return false;
    }

    VkMemoryRequirements memReq = {};
    vkGetImageMemoryRequirements(m_device, m_whiteImage, &memReq);

    uint32_t memType = FindMemoryType(memReq.memoryTypeBits, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
    if (memType == UINT32_MAX) {
        memType = FindMemoryType(memReq.memoryTypeBits,
                                 VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
    }
    if (memType == UINT32_MAX) {
        LOG_2D("ERROR: Suitable memory type not found for white fallback image!");
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        vkFreeMemory(m_device, stagingMemory, nullptr);
        return false;
    }

    VkMemoryAllocateInfo allocInfo = {};
    allocInfo.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    allocInfo.allocationSize = memReq.size;
    allocInfo.memoryTypeIndex = memType;

    if (vkAllocateMemory(m_device, &allocInfo, nullptr, &m_whiteImageMemory) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to allocate white fallback image memory!");
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        vkFreeMemory(m_device, stagingMemory, nullptr);
        return false;
    }

    vkBindImageMemory(m_device, m_whiteImage, m_whiteImageMemory, 0);

    // 3. Explicit Pipeline Barrier Transitions: UNDEFINED -> TRANSFER_DST_OPTIMAL -> SHADER_READ_ONLY_OPTIMAL
    VkCommandPool uploadPool = VK_NULL_HANDLE;
    VkCommandPoolCreateInfo poolCreate = {};
    poolCreate.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;
    poolCreate.flags = VK_COMMAND_POOL_CREATE_TRANSIENT_BIT;
    poolCreate.queueFamilyIndex = m_graphicsQueueFamily;
    if (vkCreateCommandPool(m_device, &poolCreate, nullptr, &uploadPool) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create transient command pool for white texture upload!");
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        vkFreeMemory(m_device, stagingMemory, nullptr);
        return false;
    }

    VkCommandBuffer uploadCmd = VK_NULL_HANDLE;
    VkCommandBufferAllocateInfo cmdAlloc = {};
    cmdAlloc.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;
    cmdAlloc.commandPool = uploadPool;
    cmdAlloc.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
    cmdAlloc.commandBufferCount = 1;
    if (vkAllocateCommandBuffers(m_device, &cmdAlloc, &uploadCmd) != VK_SUCCESS) {
        vkDestroyCommandPool(m_device, uploadPool, nullptr);
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        vkFreeMemory(m_device, stagingMemory, nullptr);
        return false;
    }

    VkCommandBufferBeginInfo beginInfo = {};
    beginInfo.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
    beginInfo.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    vkBeginCommandBuffer(uploadCmd, &beginInfo);

    VkImageMemoryBarrier toTransfer = {};
    toTransfer.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
    toTransfer.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED;
    toTransfer.newLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
    toTransfer.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    toTransfer.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    toTransfer.image = m_whiteImage;
    toTransfer.subresourceRange = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1 };
    toTransfer.srcAccessMask = 0;
    toTransfer.dstAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
    vkCmdPipelineBarrier(uploadCmd,
                         VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,
                         VK_PIPELINE_STAGE_TRANSFER_BIT,
                         0, 0, nullptr, 0, nullptr, 1, &toTransfer);

    VkBufferImageCopy copyRegion = {};
    copyRegion.imageSubresource = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1 };
    copyRegion.imageExtent = { 4, 4, 1 };
    vkCmdCopyBufferToImage(uploadCmd, stagingBuffer, m_whiteImage, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &copyRegion);

    VkImageMemoryBarrier toShaderRead = {};
    toShaderRead.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
    toShaderRead.oldLayout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
    toShaderRead.newLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
    toShaderRead.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    toShaderRead.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    toShaderRead.image = m_whiteImage;
    toShaderRead.subresourceRange = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1 };
    toShaderRead.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
    toShaderRead.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
    vkCmdPipelineBarrier(uploadCmd,
                         VK_PIPELINE_STAGE_TRANSFER_BIT,
                         VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT,
                         0, 0, nullptr, 0, nullptr, 1, &toShaderRead);

    vkEndCommandBuffer(uploadCmd);

    VkSubmitInfo submitInfo = {};
    submitInfo.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
    submitInfo.commandBufferCount = 1;
    submitInfo.pCommandBuffers = &uploadCmd;
    if (vkQueueSubmit(m_graphicsQueue, 1, &submitInfo, VK_NULL_HANDLE) != VK_SUCCESS ||
        vkQueueWaitIdle(m_graphicsQueue) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to submit white fallback texture layout transition!");
        vkDestroyCommandPool(m_device, uploadPool, nullptr);
        vkDestroyBuffer(m_device, stagingBuffer, nullptr);
        vkFreeMemory(m_device, stagingMemory, nullptr);
        return false;
    }

    vkDestroyCommandPool(m_device, uploadPool, nullptr);
    vkDestroyBuffer(m_device, stagingBuffer, nullptr);
    vkFreeMemory(m_device, stagingMemory, nullptr);

    // 4. Image View
    VkImageViewCreateInfo viewInfo = {};
    viewInfo.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
    viewInfo.image = m_whiteImage;
    viewInfo.viewType = VK_IMAGE_VIEW_TYPE_2D;
    viewInfo.format = VK_FORMAT_R8G8B8A8_UNORM;
    viewInfo.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
    viewInfo.subresourceRange.baseMipLevel = 0;
    viewInfo.subresourceRange.levelCount = 1;
    viewInfo.subresourceRange.baseArrayLayer = 0;
    viewInfo.subresourceRange.layerCount = 1;

    if (vkCreateImageView(m_device, &viewInfo, nullptr, &m_whiteImageView) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create white fallback VkImageView!");
        return false;
    }

    // 5. Sampler
    VkSamplerCreateInfo samplerInfo = {};
    samplerInfo.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
    samplerInfo.magFilter = VK_FILTER_LINEAR;
    samplerInfo.minFilter = VK_FILTER_LINEAR;
    samplerInfo.mipmapMode = VK_SAMPLER_MIPMAP_MODE_LINEAR;
    samplerInfo.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    samplerInfo.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    samplerInfo.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    samplerInfo.maxAnisotropy = 1.0f;

    if (vkCreateSampler(m_device, &samplerInfo, nullptr, &m_whiteSampler) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create white fallback VkSampler!");
        return false;
    }

    // 6. Descriptor Pool
    VkDescriptorPoolSize poolSize = {};
    poolSize.type = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    poolSize.descriptorCount = 256;

    VkDescriptorPoolCreateInfo poolInfo = {};
    poolInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    poolInfo.flags = VK_DESCRIPTOR_POOL_CREATE_FREE_DESCRIPTOR_SET_BIT;
    poolInfo.poolSizeCount = 1;
    poolInfo.pPoolSizes = &poolSize;
    poolInfo.maxSets = 256;

    if (vkCreateDescriptorPool(m_device, &poolInfo, nullptr, &m_descriptorPool) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create 2D VkDescriptorPool!");
        return false;
    }

    // 7. Descriptor Set Layout
    VkDescriptorSetLayoutBinding samplerLayoutBinding = {};
    samplerLayoutBinding.binding = 0;
    samplerLayoutBinding.descriptorCount = 1;
    samplerLayoutBinding.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    samplerLayoutBinding.stageFlags = VK_SHADER_STAGE_FRAGMENT_BIT;

    VkDescriptorSetLayoutCreateInfo layoutInfo = {};
    layoutInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
    layoutInfo.bindingCount = 1;
    layoutInfo.pBindings = &samplerLayoutBinding;

    if (vkCreateDescriptorSetLayout(m_device, &layoutInfo, nullptr, &m_descriptorSetLayout) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create 2D VkDescriptorSetLayout!");
        return false;
    }

    // 8. Allocate & Update White Fallback Descriptor Set (SHADER_READ_ONLY_OPTIMAL)
    VkDescriptorSetAllocateInfo allocSetInfo = {};
    allocSetInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
    allocSetInfo.descriptorPool = m_descriptorPool;
    allocSetInfo.descriptorSetCount = 1;
    allocSetInfo.pSetLayouts = &m_descriptorSetLayout;

    if (vkAllocateDescriptorSets(m_device, &allocSetInfo, &m_whiteTextureDescSet) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to allocate white fallback VkDescriptorSet!");
        return false;
    }

    VkDescriptorImageInfo descImgInfo = {};
    descImgInfo.imageLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
    descImgInfo.imageView = m_whiteImageView;
    descImgInfo.sampler = m_whiteSampler;

    VkWriteDescriptorSet descriptorWrite = {};
    descriptorWrite.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
    descriptorWrite.dstSet = m_whiteTextureDescSet;
    descriptorWrite.dstBinding = 0;
    descriptorWrite.dstArrayElement = 0;
    descriptorWrite.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    descriptorWrite.descriptorCount = 1;
    descriptorWrite.pImageInfo = &descImgInfo;

    vkUpdateDescriptorSets(m_device, 1, &descriptorWrite, 0, nullptr);

    LOG_2D("White fallback texture & descriptor set created in SHADER_READ_ONLY_OPTIMAL (DescriptorSet: 0x%p)",
           m_whiteTextureDescSet);
    return true;
}

bool Vulkan2D::CreatePipeline() {
    LOG_2D("Building Native Vulkan 2D graphics pipeline with alpha blending...");

    // 1. Shaders
    VkShaderModuleCreateInfo vertModInfo = {};
    vertModInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    vertModInfo.codeSize = sizeof(g_spv2dVertexShader);
    vertModInfo.pCode = g_spv2dVertexShader;

    VkShaderModule vertModule = VK_NULL_HANDLE;
    if (vkCreateShaderModule(m_device, &vertModInfo, nullptr, &vertModule) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create 2D vertex shader module!");
        return false;
    }

    VkShaderModuleCreateInfo fragModInfo = {};
    fragModInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    fragModInfo.codeSize = sizeof(g_spv2dFragmentShader);
    fragModInfo.pCode = g_spv2dFragmentShader;

    VkShaderModule fragModule = VK_NULL_HANDLE;
    if (vkCreateShaderModule(m_device, &fragModInfo, nullptr, &fragModule) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create 2D fragment shader module!");
        vkDestroyShaderModule(m_device, vertModule, nullptr);
        return false;
    }

    VkPipelineShaderStageCreateInfo shaderStages[2] = {};
    shaderStages[0].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    shaderStages[0].stage = VK_SHADER_STAGE_VERTEX_BIT;
    shaderStages[0].module = vertModule;
    shaderStages[0].pName = "main";

    shaderStages[1].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    shaderStages[1].stage = VK_SHADER_STAGE_FRAGMENT_BIT;
    shaderStages[1].module = fragModule;
    shaderStages[1].pName = "main";

    // 2. Vertex Input Layout: SVulkan2DVertex
    VkVertexInputBindingDescription bindingDesc = {};
    bindingDesc.binding = 0;
    bindingDesc.stride = sizeof(SVulkan2DVertex);
    bindingDesc.inputRate = VK_VERTEX_INPUT_RATE_VERTEX;

    VkVertexInputAttributeDescription attrDescs[3] = {};
    attrDescs[0].location = 0;
    attrDescs[0].binding = 0;
    attrDescs[0].format = VK_FORMAT_R32G32_SFLOAT;
    attrDescs[0].offset = offsetof(SVulkan2DVertex, x);

    attrDescs[1].location = 1;
    attrDescs[1].binding = 0;
    attrDescs[1].format = VK_FORMAT_R32G32_SFLOAT;
    attrDescs[1].offset = offsetof(SVulkan2DVertex, u);

    attrDescs[2].location = 2;
    attrDescs[2].binding = 0;
    attrDescs[2].format = VK_FORMAT_R8G8B8A8_UNORM;
    attrDescs[2].offset = offsetof(SVulkan2DVertex, color);

    VkPipelineVertexInputStateCreateInfo vtxInputInfo = {};
    vtxInputInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;
    vtxInputInfo.vertexBindingDescriptionCount = 1;
    vtxInputInfo.pVertexBindingDescriptions = &bindingDesc;
    vtxInputInfo.vertexAttributeDescriptionCount = 3;
    vtxInputInfo.pVertexAttributeDescriptions = attrDescs;

    // 3. Input Assembly
    VkPipelineInputAssemblyStateCreateInfo inputAssembly = {};
    inputAssembly.sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO;
    inputAssembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
    inputAssembly.primitiveRestartEnable = VK_FALSE;

    // 4. Viewport State (Dynamic)
    VkPipelineViewportStateCreateInfo viewportState = {};
    viewportState.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO;
    viewportState.viewportCount = 1;
    viewportState.scissorCount = 1;

    // 5. Rasterizer
    VkPipelineRasterizationStateCreateInfo rasterizer = {};
    rasterizer.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO;
    rasterizer.depthClampEnable = VK_FALSE;
    rasterizer.rasterizerDiscardEnable = VK_FALSE;
    rasterizer.polygonMode = VK_POLYGON_MODE_FILL;
    rasterizer.lineWidth = 1.0f;
    rasterizer.cullMode = VK_CULL_MODE_NONE;
    rasterizer.frontFace = VK_FRONT_FACE_CLOCKWISE;

    // 6. Multisampling
    VkPipelineMultisampleStateCreateInfo multisampling = {};
    multisampling.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO;
    multisampling.sampleShadingEnable = VK_FALSE;
    multisampling.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;

    // 7. Color Blending (Alpha Blend)
    VkPipelineColorBlendAttachmentState colorBlendAttachment = {};
    colorBlendAttachment.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT |
                                          VK_COLOR_COMPONENT_B_BIT | VK_COLOR_COMPONENT_A_BIT;
    colorBlendAttachment.blendEnable = VK_TRUE;
    colorBlendAttachment.srcColorBlendFactor = VK_BLEND_FACTOR_SRC_ALPHA;
    colorBlendAttachment.dstColorBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
    colorBlendAttachment.colorBlendOp = VK_BLEND_OP_ADD;
    colorBlendAttachment.srcAlphaBlendFactor = VK_BLEND_FACTOR_ONE;
    colorBlendAttachment.dstAlphaBlendFactor = VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA;
    colorBlendAttachment.alphaBlendOp = VK_BLEND_OP_ADD;

    VkPipelineColorBlendStateCreateInfo colorBlending = {};
    colorBlending.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO;
    colorBlending.logicOpEnable = VK_FALSE;
    colorBlending.attachmentCount = 1;
    colorBlending.pAttachments = &colorBlendAttachment;

    // 8. Dynamic States (Viewport & Scissor)
    VkDynamicState dynamicStates[] = {
        VK_DYNAMIC_STATE_VIEWPORT,
        VK_DYNAMIC_STATE_SCISSOR
    };
    VkPipelineDynamicStateCreateInfo dynamicState = {};
    dynamicState.sType = VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO;
    dynamicState.dynamicStateCount = 2;
    dynamicState.pDynamicStates = dynamicStates;

    // 9. Push Constants: (vec2 uScale, vec2 uTranslate) = 16 bytes
    VkPushConstantRange pushConstantRange = {};
    pushConstantRange.stageFlags = VK_SHADER_STAGE_VERTEX_BIT;
    pushConstantRange.offset = 0;
    pushConstantRange.size = sizeof(Vulkan2DPushConstants);

    // 10. Pipeline Layout
    VkPipelineLayoutCreateInfo pipelineLayoutInfo = {};
    pipelineLayoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    pipelineLayoutInfo.setLayoutCount = 1;
    pipelineLayoutInfo.pSetLayouts = &m_descriptorSetLayout;
    pipelineLayoutInfo.pushConstantRangeCount = 1;
    pipelineLayoutInfo.pPushConstantRanges = &pushConstantRange;

    if (vkCreatePipelineLayout(m_device, &pipelineLayoutInfo, nullptr, &m_pipelineLayout) != VK_SUCCESS) {
        LOG_2D("ERROR: Failed to create 2D VkPipelineLayout!");
        vkDestroyShaderModule(m_device, fragModule, nullptr);
        vkDestroyShaderModule(m_device, vertModule, nullptr);
        return false;
    }

    // 11. Pipeline Creation
    VkGraphicsPipelineCreateInfo pipelineInfo = {};
    pipelineInfo.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
    pipelineInfo.stageCount = 2;
    pipelineInfo.pStages = shaderStages;
    pipelineInfo.pVertexInputState = &vtxInputInfo;
    pipelineInfo.pInputAssemblyState = &inputAssembly;
    pipelineInfo.pViewportState = &viewportState;
    pipelineInfo.pRasterizationState = &rasterizer;
    pipelineInfo.pMultisampleState = &multisampling;
    pipelineInfo.pColorBlendState = &colorBlending;
    pipelineInfo.pDynamicState = &dynamicState;
    pipelineInfo.layout = m_pipelineLayout;

    VkPipelineRenderingCreateInfo renderingInfo = {};
    renderingInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_RENDERING_CREATE_INFO;
    renderingInfo.colorAttachmentCount = 1;
    renderingInfo.pColorAttachmentFormats = &m_colorFormat;

    bool useDynamicRendering = VulkanContext::Get().IsDynamicRenderingSupported();
    if (useDynamicRendering) {
        pipelineInfo.pNext = &renderingInfo;
        pipelineInfo.renderPass = VK_NULL_HANDLE;
        pipelineInfo.subpass = 0;
        LOG_2D("Configuring 2D Graphics Pipeline with Vulkan 1.3 Core Dynamic Rendering (VkPipelineRenderingCreateInfo, Format %d)", m_colorFormat);
    } else {
        pipelineInfo.renderPass = m_renderPass;
        pipelineInfo.subpass = 0;
    }

    VkPipelineCache pCache = VulkanContext::Get().GetPipelineCache();
    VkResult res = vkCreateGraphicsPipelines(m_device, pCache, 1, &pipelineInfo, nullptr, &m_pipeline);

    if (res != VK_SUCCESS && useDynamicRendering) {
        LOG_2D("Dynamic rendering pipeline failed (code %d), falling back to standard render pass...", res);
        pipelineInfo.pNext = nullptr;
        pipelineInfo.renderPass = m_renderPass;
        res = vkCreateGraphicsPipelines(m_device, pCache, 1, &pipelineInfo, nullptr, &m_pipeline);
    }

    vkDestroyShaderModule(m_device, fragModule, nullptr);
    vkDestroyShaderModule(m_device, vertModule, nullptr);

    if (res != VK_SUCCESS) {
        LOG_2D("ERROR: vkCreateGraphicsPipelines failed with code %d!", res);
        return false;
    }

    LOG_2D("Native Vulkan 2D Pipeline Created Successfully! (Pipeline: 0x%p, Layout: 0x%p, Cache: 0x%p)",
           m_pipeline, m_pipelineLayout, pCache);
    return true;
}

void Vulkan2D::ResetBatch() {
    std::lock_guard<std::mutex> lock(m_batchMutex);
    if (m_hasStartedAnyFrame) {
        m_activeFrameSlot = (m_activeFrameSlot + 1) % MAX_FRAMES_IN_FLIGHT;
    } else {
        m_activeFrameSlot = 0;
        m_hasStartedAnyFrame = true;
    }
    m_vertexCount = 0;
    m_indexCount = 0;
    m_batches.clear();
    m_currentDescriptorSet = VK_NULL_HANDLE;
    m_currentScissor = {{0, 0}, {m_width, m_height}};
}

void Vulkan2D::AddRect(float x, float y, float w, float h,
                       float s0, float t0, float s1, float t1,
                       uint32_t color1, uint32_t color2,
                       VkDescriptorSet descSet) {
    if (!m_bInitialized) return;

    if (descSet == VK_NULL_HANDLE) {
        descSet = m_whiteTextureDescSet;
    }

    std::lock_guard<std::mutex> lock(m_batchMutex);
    FrameRingSlot& ring = m_frameRings[m_activeFrameSlot];
    if (!ring.pMappedVertices || !ring.pMappedIndices) return;

    constexpr uint32_t maxVertices = static_cast<uint32_t>(VTX_BUFFER_SIZE / sizeof(SVulkan2DVertex));
    constexpr uint32_t maxIndices = static_cast<uint32_t>(IDX_BUFFER_SIZE / sizeof(uint32_t));

    if (m_vertexCount + 4 > maxVertices || m_indexCount + 6 > maxIndices) {
        LOG_2D("WARNING: 2D ring buffer slot %u full! Vertex: %u/%u, Index: %u/%u",
               m_activeFrameSlot, m_vertexCount, maxVertices, m_indexCount, maxIndices);
        return;
    }

    bool newBatch = m_batches.empty() ||
                    (m_batches.back().descriptorSet != descSet) ||
                    (std::memcmp(&m_batches.back().scissor, &m_currentScissor, sizeof(VkRect2D)) != 0);

    if (newBatch) {
        Vulkan2DDrawBatch batch = {};
        batch.firstIndex = m_indexCount;
        batch.indexCount = 0;
        batch.vertexOffset = 0;
        batch.descriptorSet = descSet;
        batch.scissor = m_currentScissor;
        m_batches.push_back(batch);
    }

    uint32_t vBase = m_vertexCount;
    ring.pMappedVertices[vBase + 0] = { x,     y,     s0, t0, color1 };
    ring.pMappedVertices[vBase + 1] = { x + w, y,     s1, t0, color1 };
    ring.pMappedVertices[vBase + 2] = { x + w, y + h, s1, t1, color2 };
    ring.pMappedVertices[vBase + 3] = { x,     y + h, s0, t1, color2 };

    uint32_t iBase = m_indexCount;
    ring.pMappedIndices[iBase + 0] = vBase + 0;
    ring.pMappedIndices[iBase + 1] = vBase + 1;
    ring.pMappedIndices[iBase + 2] = vBase + 2;
    ring.pMappedIndices[iBase + 3] = vBase + 2;
    ring.pMappedIndices[iBase + 4] = vBase + 3;
    ring.pMappedIndices[iBase + 5] = vBase + 0;

    m_vertexCount += 4;
    m_indexCount += 6;
    m_batches.back().indexCount += 6;
}

void Vulkan2D::AddQuad(const float* v, const float* tc, uint32_t color, VkDescriptorSet descSet) {
    if (!m_bInitialized || !v || !tc) return;
    if (descSet == VK_NULL_HANDLE) descSet = m_whiteTextureDescSet;

    std::lock_guard<std::mutex> lock(m_batchMutex);
    FrameRingSlot& ring = m_frameRings[m_activeFrameSlot];
    if (!ring.pMappedVertices || !ring.pMappedIndices) return;

    constexpr uint32_t maxVertices = static_cast<uint32_t>(VTX_BUFFER_SIZE / sizeof(SVulkan2DVertex));
    constexpr uint32_t maxIndices = static_cast<uint32_t>(IDX_BUFFER_SIZE / sizeof(uint32_t));

    if (m_vertexCount + 4 > maxVertices || m_indexCount + 6 > maxIndices) return;

    bool newBatch = m_batches.empty() ||
                    (m_batches.back().descriptorSet != descSet) ||
                    (std::memcmp(&m_batches.back().scissor, &m_currentScissor, sizeof(VkRect2D)) != 0);

    if (newBatch) {
        Vulkan2DDrawBatch batch = {};
        batch.firstIndex = m_indexCount;
        batch.indexCount = 0;
        batch.vertexOffset = 0;
        batch.descriptorSet = descSet;
        batch.scissor = m_currentScissor;
        m_batches.push_back(batch);
    }

    uint32_t vBase = m_vertexCount;
    for (int i = 0; i < 4; ++i) {
        ring.pMappedVertices[vBase + i] = { v[i * 2 + 0], v[i * 2 + 1], tc[i * 2 + 0], tc[i * 2 + 1], color };
    }

    uint32_t iBase = m_indexCount;
    ring.pMappedIndices[iBase + 0] = vBase + 0;
    ring.pMappedIndices[iBase + 1] = vBase + 1;
    ring.pMappedIndices[iBase + 2] = vBase + 2;
    ring.pMappedIndices[iBase + 3] = vBase + 2;
    ring.pMappedIndices[iBase + 4] = vBase + 3;
    ring.pMappedIndices[iBase + 5] = vBase + 0;

    m_vertexCount += 4;
    m_indexCount += 6;
    m_batches.back().indexCount += 6;
}

void Vulkan2D::AddTri(const float* v, const float* tc, uint32_t color, VkDescriptorSet descSet) {
    if (!m_bInitialized || !v || !tc) return;
    if (descSet == VK_NULL_HANDLE) descSet = m_whiteTextureDescSet;

    std::lock_guard<std::mutex> lock(m_batchMutex);
    FrameRingSlot& ring = m_frameRings[m_activeFrameSlot];
    if (!ring.pMappedVertices || !ring.pMappedIndices) return;

    constexpr uint32_t maxVertices = static_cast<uint32_t>(VTX_BUFFER_SIZE / sizeof(SVulkan2DVertex));
    constexpr uint32_t maxIndices = static_cast<uint32_t>(IDX_BUFFER_SIZE / sizeof(uint32_t));

    if (m_vertexCount + 3 > maxVertices || m_indexCount + 3 > maxIndices) return;

    bool newBatch = m_batches.empty() ||
                    (m_batches.back().descriptorSet != descSet) ||
                    (std::memcmp(&m_batches.back().scissor, &m_currentScissor, sizeof(VkRect2D)) != 0);

    if (newBatch) {
        Vulkan2DDrawBatch batch = {};
        batch.firstIndex = m_indexCount;
        batch.indexCount = 0;
        batch.vertexOffset = 0;
        batch.descriptorSet = descSet;
        batch.scissor = m_currentScissor;
        m_batches.push_back(batch);
    }

    uint32_t vBase = m_vertexCount;
    for (int i = 0; i < 3; ++i) {
        ring.pMappedVertices[vBase + i] = { v[i * 2 + 0], v[i * 2 + 1], tc[i * 2 + 0], tc[i * 2 + 1], color };
    }

    uint32_t iBase = m_indexCount;
    ring.pMappedIndices[iBase + 0] = vBase + 0;
    ring.pMappedIndices[iBase + 1] = vBase + 1;
    ring.pMappedIndices[iBase + 2] = vBase + 2;

    m_vertexCount += 3;
    m_indexCount += 3;
    m_batches.back().indexCount += 3;
}

void Vulkan2D::AddLine(float x1, float y1, float x2, float y2, uint32_t color) {
    float dx = x2 - x1;
    float dy = y2 - y1;
    float len = sqrtf(dx * dx + dy * dy);
    if (len < 0.0001f) return;

    float nx = -dy / len * 0.5f;
    float ny =  dx / len * 0.5f;

    float v[8] = {
        x1 + nx, y1 + ny,
        x2 + nx, y2 + ny,
        x2 - nx, y2 - ny,
        x1 - nx, y1 - ny
    };
    float tc[8] = { 0.f, 0.f, 1.f, 0.f, 1.f, 1.f, 0.f, 1.f };

    AddQuad(v, tc, color, m_whiteTextureDescSet);
}

void Vulkan2D::SetScissor(int32_t x, int32_t y, uint32_t w, uint32_t h) {
    std::lock_guard<std::mutex> lock(m_batchMutex);
    m_currentScissor.offset.x = x;
    m_currentScissor.offset.y = y;
    m_currentScissor.extent.width = w;
    m_currentScissor.extent.height = h;
}

void Vulkan2D::RecordDrawCommands(VkCommandBuffer cmd, uint32_t viewportWidth, uint32_t viewportHeight) {
    KONGOR_TRACY_ZONE_SCOPED_N("Vulkan2D::RecordDrawCommands");
    std::lock_guard<std::mutex> lock(m_batchMutex);
    if (m_indexCount == 0 || m_batches.empty() || viewportWidth == 0 || viewportHeight == 0) return;

    const FrameRingSlot& ring = m_frameRings[m_activeFrameSlot];
    if (ring.vtxBuffer == VK_NULL_HANDLE || ring.idxBuffer == VK_NULL_HANDLE) return;

    // 1. Bind 2D Graphics Pipeline
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, m_pipeline);

    // 2. Set Dynamic Viewport
    VkViewport vp = {};
    vp.x = 0.0f;
    vp.y = 0.0f;
    vp.width = static_cast<float>(viewportWidth);
    vp.height = static_cast<float>(viewportHeight);
    vp.minDepth = 0.0f;
    vp.maxDepth = 1.0f;
    vkCmdSetViewport(cmd, 0, 1, &vp);

    // 3. Push Constants: Orthographic Projection to Vulkan NDC
    Vulkan2DPushConstants pc = {};
    pc.scale[0] = 2.0f / static_cast<float>(viewportWidth);
    pc.scale[1] = 2.0f / static_cast<float>(viewportHeight);
    pc.translate[0] = -1.0f;
    pc.translate[1] = -1.0f;
    vkCmdPushConstants(cmd, m_pipelineLayout, VK_SHADER_STAGE_VERTEX_BIT, 0, sizeof(Vulkan2DPushConstants), &pc);

    // 4. Bind Active Frame's Host-Coherent Ring Buffers
    VkDeviceSize offset = 0;
    vkCmdBindVertexBuffers(cmd, 0, 1, &ring.vtxBuffer, &offset);
    vkCmdBindIndexBuffer(cmd, ring.idxBuffer, 0, VK_INDEX_TYPE_UINT32);

    // 5. Draw Batches
    VkDescriptorSet boundDescSet = VK_NULL_HANDLE;
    for (const auto& batch : m_batches) {
        if (batch.indexCount == 0) continue;

        if (batch.scissor.extent.width > 0 && batch.scissor.extent.height > 0) {
            vkCmdSetScissor(cmd, 0, 1, &batch.scissor);
        } else {
            VkRect2D fullRect = {{0, 0}, {viewportWidth, viewportHeight}};
            vkCmdSetScissor(cmd, 0, 1, &fullRect);
        }

        if (batch.descriptorSet != boundDescSet && batch.descriptorSet != VK_NULL_HANDLE) {
            vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, m_pipelineLayout,
                                    0, 1, &batch.descriptorSet, 0, nullptr);
            boundDescSet = batch.descriptorSet;
        }

        vkCmdDrawIndexed(cmd, batch.indexCount, 1, batch.firstIndex, batch.vertexOffset, 0);
    }
}

void Vulkan2D::Shutdown() {
    if (!m_bInitialized && m_device == VK_NULL_HANDLE) return;
    m_bInitialized = false;
    LOG_2D("Shutting down Native Vulkan 2D subsystem...");

    if (m_device != VK_NULL_HANDLE) {
        vkDeviceWaitIdle(m_device);

        if (m_pipeline != VK_NULL_HANDLE) {
            vkDestroyPipeline(m_device, m_pipeline, nullptr);
            m_pipeline = VK_NULL_HANDLE;
        }
        if (m_pipelineLayout != VK_NULL_HANDLE) {
            vkDestroyPipelineLayout(m_device, m_pipelineLayout, nullptr);
            m_pipelineLayout = VK_NULL_HANDLE;
        }
        if (m_descriptorSetLayout != VK_NULL_HANDLE) {
            vkDestroyDescriptorSetLayout(m_device, m_descriptorSetLayout, nullptr);
            m_descriptorSetLayout = VK_NULL_HANDLE;
        }
        if (m_descriptorPool != VK_NULL_HANDLE) {
            vkDestroyDescriptorPool(m_device, m_descriptorPool, nullptr);
            m_descriptorPool = VK_NULL_HANDLE;
        }
        m_whiteTextureDescSet = VK_NULL_HANDLE;
        if (m_renderPass != VK_NULL_HANDLE) {
            vkDestroyRenderPass(m_device, m_renderPass, nullptr);
            m_renderPass = VK_NULL_HANDLE;
        }

        // Fallback white texture
        if (m_whiteSampler != VK_NULL_HANDLE) {
            vkDestroySampler(m_device, m_whiteSampler, nullptr);
            m_whiteSampler = VK_NULL_HANDLE;
        }
        if (m_whiteImageView != VK_NULL_HANDLE) {
            vkDestroyImageView(m_device, m_whiteImageView, nullptr);
            m_whiteImageView = VK_NULL_HANDLE;
        }
        if (m_whiteImage != VK_NULL_HANDLE) {
            vkDestroyImage(m_device, m_whiteImage, nullptr);
            m_whiteImage = VK_NULL_HANDLE;
        }
        if (m_whiteImageMemory != VK_NULL_HANDLE) {
            vkFreeMemory(m_device, m_whiteImageMemory, nullptr);
            m_whiteImageMemory = VK_NULL_HANDLE;
        }

        // Per-frame ring buffers
        for (uint32_t slot = 0; slot < MAX_FRAMES_IN_FLIGHT; ++slot) {
            FrameRingSlot& ring = m_frameRings[slot];
            if (ring.pMappedVertices) {
                vkUnmapMemory(m_device, ring.vtxMemory);
                ring.pMappedVertices = nullptr;
            }
            if (ring.vtxBuffer != VK_NULL_HANDLE) {
                vkDestroyBuffer(m_device, ring.vtxBuffer, nullptr);
                ring.vtxBuffer = VK_NULL_HANDLE;
            }
            if (ring.vtxMemory != VK_NULL_HANDLE) {
                vkFreeMemory(m_device, ring.vtxMemory, nullptr);
                ring.vtxMemory = VK_NULL_HANDLE;
            }

            if (ring.pMappedIndices) {
                vkUnmapMemory(m_device, ring.idxMemory);
                ring.pMappedIndices = nullptr;
            }
            if (ring.idxBuffer != VK_NULL_HANDLE) {
                vkDestroyBuffer(m_device, ring.idxBuffer, nullptr);
                ring.idxBuffer = VK_NULL_HANDLE;
            }
            if (ring.idxMemory != VK_NULL_HANDLE) {
                vkFreeMemory(m_device, ring.idxMemory, nullptr);
                ring.idxMemory = VK_NULL_HANDLE;
            }
        }

        m_device = VK_NULL_HANDLE;
    }

    LOG_2D("Native Vulkan 2D subsystem cleanly shut down.");
}
